import {useTournamentStore} from "stores/tournament-store";
import ConfirmActionComponent from "pages/shared/confirmActionComponent.vue";
import JsonEditorVue from 'json-editor-vue'
import type {Mode} from "vanilla-jsoneditor";
import moment from "moment";
import {api} from "boot/axios";

export default defineComponent({
  name: "categoriesTab",
  components: {
    ConfirmActionComponent,
    JsonEditorVue,
    draggable: VueDraggableNext,
  },
  data: () => ({
    filterRoundDialog: false,
    alertDialog: false,
    alertDialog2: false,
    eventDetailDialog: false,
    drag: false,
    eventSelected: null as any,
    modeEditor: 'text' as Mode.tree | Mode.text | Mode.table,
  }),
  computed: {
    ...mapState(useTournamentStore, ['tournament']),
    dragOptions() {
      return {
        animation: 200,
        ghostClass: "ghost"
      };
    }
  },
  methods: {
    copy(value: string) {
      void copyToClipboard(value)
        .then(() => {
          this.$q.notify({
            message: 'ID copiado al portapapeles',
            type: 'positive',
            position: 'top'
          })
        })
    },
    changeDragDrog(data: any) {
      changeLoading(true)
      const payload = {
        events: this.tournament.events.map((e: any, i: number) => ({id: e.id, data: {index: i+1}}))
      }
      void patchEvents_service(this.tournament.id, payload)
        .then(() => {
          this.$q.notify({
            message: 'Orden de eventos actualizado',
            type: 'positive',
            position: 'top'
          })
          void getTournament(this.tournament.id)
        })
        .finally(() => changeLoading(false))
    },
    updateEvent() {
      changeLoading(true)
      const payload = {
        events: [
          {
            id: this.eventSelected.id,
            data: {
              name: this.eventSelected.name,
              num_participants: Number(this.eventSelected.num_participants),
              sport: this.eventSelected.sport,
              public: get(this.eventSelected, 'public', false),
              is_started: get(this.eventSelected, 'is_started', false),
              is_ended: get(this.eventSelected, 'is_ended', false),
              is_closed_register: get(this.eventSelected, 'is_closed_register', false),
              ranking_avg_diff: get(this.eventSelected, 'ranking_avg_diff', false),
              is_qualify: get(this.eventSelected, 'is_qualify', false),
              is_show_ranking: get(this.eventSelected, 'is_show_ranking', false),
              is_show_team: get(this.eventSelected, 'is_show_team', false),
              is_show_tree: get(this.eventSelected, 'is_show_tree', false),
              is_show_draw: get(this.eventSelected, 'is_show_draw', false),
              no_shows_list_users_joined: get(this.eventSelected, 'no_shows_list_users_joined', false),
              allow_single_registration: get(this.eventSelected, 'allow_single_registration', false),
              dynamic_form: get(this.eventSelected, 'dynamic_form', [])
            }
          }
        ]
      }
      void patchEvents_service(this.tournament.id, payload)
        .then(() => {
          this.$q.notify({
            message: 'Orden de eventos actualizado',
            type: 'positive',
            position: 'top'
          })
          void getTournament(this.tournament.id)
          this.eventDetailDialog = false
        })
        .finally(() => changeLoading(false))
    },
    duplicateCategories(event: any) {
      changeLoading(true)
      void duplicateEvent_service(this.tournament.id, event.id)
        .then(() => {
          this.$q.notify({
            message: 'Orden de eventos actualizado',
            type: 'positive',
            position: 'top'
          })
          void getTournament(this.tournament.id)
        })
        .finally(() => changeLoading(false))
    },
    generateClasification() {
      changeLoading(true)
      void generateTableClassification_service(this.tournament.id, this.eventSelected.id)
        .then(() => {
          this.$q.notify({
            message: 'tabla de clasificación generada',
            type: 'positive',
            position: 'top'
          })
          void getTournament(this.tournament.id)
          this.eventDetailDialog = false
        })
        .finally(() => changeLoading(false))
    },
    deleteCategories() {
      changeLoading(true)
      void deleteCategories_service(this.tournament.id, this.eventSelected.id)
        .then(() => {
          this.$q.notify({
            message: 'Evento eliminado correctamente',
            type: 'positive',
            position: 'top'
          })
          void getTournament(this.tournament.id)
        })
        .finally(() => changeLoading(false))
    },
    showDate(initial: number, ended: string) {
      return moment.unix(initial).format('DD MMMM')+' al '+moment(ended).format('DD MMMM [del] YYYY')
    },
    shareCategories(event: any) {
      const text = `*Únete al evento:*

📢 ${event.name}
📅 ${this.showDate(event.start_at_date_time._seconds, event.end_at_date_time)}
🕜 12:00 a.m - 12:00 a.m
📍 ${event.field.name}

*Costo:*  ${event.currency}${event.inscription_price_per_person} por ${event.initial_type_participation_payment}.

*Persona de contacto o responsable:*
${event.payment_manager.name}
tel ${event.payment_manager.phone}


Participa aquí
https://klubo.app/invite?eid=${event.id}`;
      void copyToClipboard(text)
        .then(() => {
          this.$q.notify({
            message: 'Link copiado al portapapeles',
            type: 'positive',
            position: 'top'
          })
        })
    },
    updateFilterRounds() {
      changeLoading(true)
      const payload = {
        events: [
          {
            id: this.eventSelected.id,
            data: {
              filter_rounds: this.eventSelected.filter_rounds
            }
          }
        ]
      }
      void patchEvents_service(this.tournament.id, payload)
        .then(() => {
          this.filterRoundDialog = false
          void getTournament(this.tournament.id)
        })
    },
    autocomplete() {
      changeLoading(true)
      void api.post('autocompleteFiltersEvent', {
        event: this.eventSelected.id
      }).then(() => {
        this.filterRoundDialog = false
        this.$q.notify({
          message: 'Filtro generado automaticamente.',
          type: 'positive',
          position: 'top'
        })
        void getTournament(this.tournament.id)
      })
    }
  }
})
</script>

<style lang="css">
.flip-list-move {
  transition: transform 0.5s;
}
.no-move {
  transition: transform 0s;
}
.ghost {
  opacity: 0.5;
  background: #c8ebfb;
  border-radius: 50px;
}
.list-group {
  min-height: 20px;
}
.list-group-item div {
  cursor: pointer;
}

.grid-cols-16 {
  grid-template-columns: repeat(16, minmax(0, 1fr));
}
</style>

